package dev.yab.sync

import dev.yab.browser.model.*
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import org.junit.Assert.*
import org.junit.Test

class LaunchKeyboardCompatibilityTest {
    private val json = Json { encodeDefaults = true }
    // Exact pre128 encodeDefaults snapshot bytes, not generated by the new serializer.
    private val old = """{"schema":1,"spaces":[{"id":"space","name":"Before","emoji":"","color":4293847522,"ownSignIns":false,"isPrivate":false,"tabs":[],"currentTabId":null,"folders":[]}],"selectedSpaceId":"space","history":[],"settings":{"appearance":"SYSTEM","searchEngine":"GOOGLE","customSearchTemplate":"","blocksAds":true,"darkenWebsites":false,"autoClearToday":false,"lockPrivate":true,"welcomed":false,"syncHistory":true,"macTabs":false,"swipeAnywhere":true},"recency":{},"historyForgetting":{"places":{},"spans":[]}}"""
    private val oldHash = "2bfff75209cb635aeacde82de357401c7915c710ef4136e7e0bbf1f7bbda1e64"

    @Test fun preUpgradeCheckpointStillRestoresItsExactFixedJsonHashWithoutEmittingDefaultTrue() {
        val before = json.decodeFromString<BrowserSnapshot>(old)
        assertTrue(before.settings.openKeyboardAtLaunch)
        assertEquals(old, json.encodeToString(before)); assertEquals(oldHash, BrowserSnapshotHash.of(before))
        val target = before.copy(spaces = before.spaces.map { it.copy(name = "From Mac") })
        val checkpoint = BrowserSyncCheckpoint(account = "a", device = "d", target = target, knownLocalHashes = listOf(oldHash), localSearch = false)
        assertEquals(target, checkpoint.restore(before))
        val explicitLocal = before.copy(settings = before.settings.copy(openKeyboardAtLaunch = false))
        assertEquals(explicitLocal, checkpoint.restore(explicitLocal))
    }

    @Test fun explicitFalsePersistsAndActualSyncProjectionKeepsTheLocalChoice() {
        val before = json.decodeFromString<BrowserSnapshot>(old)
        val local = before.copy(settings = before.settings.copy(openKeyboardAtLaunch = false))
        assertTrue(json.encodeToString(local).contains("\"openKeyboardAtLaunch\":false"))
        assertFalse(json.decodeFromString<BrowserSnapshot>(json.encodeToString(local)).settings.openKeyboardAtLaunch)
        assertFalse(BrowserSyncCodec.project(local, emptyList(), "android").settings.openKeyboardAtLaunch)
        assertFalse(BrowserSyncCodec.changes(local, before, emptyList(), "android").fields.values.any { "openKeyboardAtLaunch" in it.keys })
    }

    @Test fun actualGeneralSearchIndexIncludesTheRealDefaultOnSwitch() {
        assertTrue(BrowserSettings().openKeyboardAtLaunch)
        val pages = SettingsSearchIndex.pages(BrowserSettings(), emptyList(), SettingsSearchAvailability())
        val match = SettingsSearchIndex.matches("open keyboard", pages).single()
        assertEquals(SettingsPage.GENERAL, match.page); assertEquals(SettingsRowId.LAUNCH_KEYBOARD, match.row?.id)
    }
}
